resources.string:
// Глобальные переменные сохраняются между вызовами в SystemUI, но могут сброситься в любой момент.
var calls = 0;

function run(ctx) {
  var input = ctx.input || {};
  if (typeof input.text !== 'string') return null;  // Сохранить исходный текст.
  calls++;
  return input.text + ' ' + oshin.fmtDate(ctx.now, 'E');
}
